declare(strict_types=1);

namespace Stuck1A\StuckMVC\Core\Routing;

/**
 * Everything the kernel needs to know about the application structure: routes, actions and widgets.
 * Generated by the {@see MapBuilder} and cached between requests.
 */
final class ApplicationMap
{
    /**
     * @param array<string, array{class-string, string}> $actions Action name => [controller class, method]
     * @param array<string, class-string>                $widgets Lower-cased widget name => widget class
     */
    public function __construct(
        public readonly RouteCollection $routes,
        public readonly array $actions = [],
        public readonly array $widgets = [],
    ) {
    }

    /**
     * @return array{class-string, string}|null
     */
    public function action(string $name): ?array
    {
        return $this->actions[$name] ?? null;
    }

    /**
     * @return class-string|null
     */
    public function widget(string $name): ?string
    {
        return $this->widgets[strtolower($name)] ?? null;
    }

    /**
     * @return array<string, mixed>
     */
    public function toArray(): array
    {
        return ['routes' => $this->routes->toArray(), 'actions' => $this->actions, 'widgets' => $this->widgets];
    }

    /**
     * @param array<string, mixed> $data
     */
    public static function fromArray(array $data): self
    {
        return new self(RouteCollection::fromArray($data['routes'] ?? []), $data['actions'] ?? [], $data['widgets'] ?? []);
    }
}
